from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump_to = dict(jumps)
    resolved = list(range(n + 1))
    for start in jump_to:
        resolved[start] = -1

    for start in jump_to:
        path = []
        cell = start
        while resolved[cell] == -1:
            path.append(cell)
            cell = jump_to[cell]
        for cell_on_path in path:
            resolved[cell_on_path] = resolved[cell]

    states = [0]
    state_index = {0: 0}
    transitions = []

    for position in states:
        counts = {}
        if position != n:
            for roll in range(1, m + 1):
                landing = position + roll
                if landing > n:
                    landing = 2 * n - landing
                destination = resolved[landing]
                counts[destination] = counts.get(destination, 0) + 1
                if destination not in state_index:
                    state_index[destination] = len(states)
                    states.append(destination)
        transitions.append(counts)

    if n not in state_index:
        return None

    reverse = [[] for _ in states]
    for source, counts in enumerate(transitions):
        for destination in counts:
            reverse[state_index[destination]].append(source)

    reachable_to_end = {state_index[n]}
    pending = [state_index[n]]
    while pending:
        for predecessor in reverse[pending.pop()]:
            if predecessor not in reachable_to_end:
                reachable_to_end.add(predecessor)
                pending.append(predecessor)

    if len(reachable_to_end) != len(states):
        return None

    transient = [position for position in states if position != n]
    equation_index = {position: i for i, position in enumerate(transient)}
    size = len(transient)
    matrix = [[0] * (size + 1) for _ in range(size)]

    for i, position in enumerate(transient):
        matrix[i][i] = m
        matrix[i][size] = m
        for destination, count in transitions[state_index[position]].items():
            if destination != n:
                matrix[i][equation_index[destination]] -= count

    # Fraction-free Gaussian elimination (Bareiss algorithm).
    previous_pivot = 1
    for k in range(size - 1):
        if matrix[k][k] == 0:
            replacement = next(
                i for i in range(k + 1, size) if matrix[i][k] != 0
            )
            matrix[k], matrix[replacement] = matrix[replacement], matrix[k]

        pivot_row = matrix[k]
        pivot = pivot_row[k]
        for i in range(k + 1, size):
            row = matrix[i]
            factor = row[k]
            for j in range(k + 1, size + 1):
                row[j] = (
                    pivot * row[j] - factor * pivot_row[j]
                ) // previous_pivot
            row[k] = 0
        previous_pivot = pivot

    expectation = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * expectation[j]
        expectation[i] = value / matrix[i][i]

    answer = expectation[equation_index[0]]
    return [answer.numerator, answer.denominator]
